var colors = ['#1f77b4','#ff7f0e','#2ca02c','#d62728','#9467bd','#8c564b','#e377c2','#17becf','#bcbd22','#7f7f7f','#aec7e8','#ffbb78','#98df8a','#ff9896','#c5b0d5','#c49c94','#f7b6d2','#c7c7c7','#dbdb8d','#9edae5','#393b79'];

function makeBarChart(title, unit, field, divisor, maxVal) {
  var html = '<div style="margin:10px 0"><h3 style="color:#03a9f4;margin:5px 0">' + title + '</h3>';
  html += '<div style="display:flex;flex-wrap:wrap;gap:2px">';
  var items = [];
  for (var i = 0; i < rows.length; i++) {
    var r = rows[i];
    var val = r[field];
    if (val !== null && val !== undefined) {
      items.push({name: r['node_id'] || '?', val: val / (divisor || 1)});
    }
  }
  for (var j = 0; j < items.length; j++) {
    var pct = Math.min(100, (items[j].val / maxVal) * 100);
    var c = colors[j % colors.length];
    var displayVal = divisor > 1 ? items[j].val.toFixed(1) : Math.round(items[j].val);
    html += '<div style="flex:1;min-width:40px;max-width:80px;text-align:center;font-size:10px">';
    html += '<div style="height:80px;display:flex;align-items:flex-end;justify-content:center">';
    html += '<div style="width:100%;height:' + Math.max(3, pct) + '%;background:' + c + ';border-radius:3px 3px 0 0;min-height:3px"></div>';
    html += '</div>';
    html += '<div style="color:#fff;font-weight:bold;padding:2px 0">' + displayVal + '</div>';
    html += '<div style="color:#999;font-size:9px;overflow:hidden;text-overflow:ellipsis">' + items[j].name.replace(/^(poll_|temp_|noise_)/,'') + '</div>';
    html += '</div>';
  }
  html += '</div>';
  html += '<div style="color:#666;font-size:11px;margin-top:3px">Unit: ' + unit + ' | ' + items.length + ' nodes</div></div>';
  return html;
}

